def score_pos(fen, side_to_move_is_white):
    # use simulate_move to inspect no move
    d = simulate_move(fen, None)
    if d['game_over']:
        res = d.get('result','')
        if '1-0' in res or d.get('winner')=='white':
            return 100000
        elif '0-1' in res or d.get('winner')=='black':
            return -100000
        else:
            return 0
    sq = d['squares']
    score = 0
    val = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0}
    central = {'d4','e4','d5','e5'}
    white_check = False
    black_check = False
    # determine king positions to detect check
    wk = None; bk = None
    for r in range(8):
        for c in range(8):
            p = sq[r][c]
            if p=='K': wk=(r,c)
            elif p=='k': bk=(r,c)
    # detect check by scanning attackers
    def on_board(r,c): return 0<=r<8 and 0<=c<8
    # simple: use legal_moves? not directly. Just approximate with all-white attacks
    # We'll skip precise check detection; use simple: if side to move, check via simulate? 
    # We'll approximate check by scanning knight/pawn/diagonal
    for r in range(8):
        for c in range(8):
            p = sq[r][c]
            if p=='.' or p=='k': 
                if p=='k': score -= 0
                continue
            if p.isupper():
                score += val[p]
                if (chr(c+97)+str(8-r)) in central: score += 12
            else:
                score -= val[p.lower() if False else p]
                if (chr(c+97)+str(8-r)) in central: score -= 12
    # note lowercase value mapping
    return score

